import React, { useState } from 'react';
import Sidebar from './Sidebar';

export default function AdminDashboard({ userName, onLogoutClick }) {
  const [currentSubPage, setCurrentSubPage] = useState('Overview');

  return (
    // 1. මුළු පේජ් එකම Column එකක් විදියට ගන්නවා (Header උඩින්ම තියන්න)
    <div style={{ display: 'flex', flexDirection: 'column', height: '100vh', width: '100vw' }}>
      
      {/* 2. Header එක (සුදු පාට තීරුව) */}
      <header style={{ 
        height: '70px', backgroundColor: '#ffffff', display: 'flex', 
        alignItems: 'center', padding: '0 30px', borderBottom: '1px solid #e2e8f0' 
      }}>
        {/* මෙතනට ඔයාගේ Logo එක දාන්න */}
        <img src="/logo.png" alt="Logo" style={{ height: '40px', marginRight: '15px' }} />
        <div style={{ fontWeight: 'bold', fontSize: '20px', color: '#15803d' }}>AuraPen Saku</div>
        <div style={{ marginLeft: 'auto', fontSize: '18px', fontWeight: '600' }}>Welcome, Admin User 👋</div>
      </header>

      {/* 3. Sidebar සහ Content එක එක පේළියට (Row) */}
      <div style={{ display: 'flex', flex: 1, overflow: 'hidden' }}>
        
        {/* Sidebar එක */}
        <div style={{ width: '260px', backgroundColor: '#15803d' }}>
           <Sidebar 
             currentSubPage={currentSubPage} 
             setCurrentSubPage={setCurrentSubPage} 
             onLogoutClick={onLogoutClick} 
           />
        </div>

        {/* Content Area (කාඩ්ස් සහ චාට්ස් ටික) */}
        <div style={{ flex: 1, padding: '20px', overflowY: 'auto', backgroundColor: '#f1f5f9' }}>
           <h2>{currentSubPage}</h2>
           {/* මෙතනට ඔයාගේ කාඩ්ස් සහ චාට්ස් ටික දාන්න */}
        </div>
        
      </div>
    </div>
  );
}
